          "conditions": [
            {
              "description": "The assistant must attempt all possible diagnostic steps before escalating to a human agent.",
              "status": "UNSATISFIED",
              "reason": "The tool call `check_network_status` is a single diagnostic step and does not address the full range of MMS prerequisites (e.g., network mode, APN/MMSC, Wi-Fi Calling, app permissions). The policy requires **exhaustive diagnostics** before escalation.",
              "evidence": [
                {
                  "source_id": "q4",
                  "actor": "system",
                  "quote": "Make sure you try all the possible ways to resolve the user's issue before transferring to a human agent.",
                  "fact": "The policy mandates attempting all possible resolutions, not just a single diagnostic step."
                }
              ]
            }
          ],
          "prerequisites": [],
          "exceptions": {
            "status": "NO_EXCEPTION",
            "reason": "No exceptions apply to the requirement of exhausting all diagnostic steps before escalation.",
            "evidence": []
          },
          "conclusion": "VIOLATED",
          "reason": "The tool call `check_network_status` is a **partial and insufficient** step in the MMS troubleshooting process. The policy requires verifying **all** prerequisites (network mode, APN/MMSC, Wi-Fi Calling, app permissions) before concluding diagnostics or escalating. This tool call alone does not satisfy the policy's requirement to attempt all possible resolutions.",
          "supporting_evidence": [
            {
              "source_id": "q4",
              "actor": "system",
              "quote": "Make sure you try all the possible ways to resolve the user's issue before transferring to a human agent.",
              "fact": "The policy explicitly requires exhaustive diagnostics."
            },
            {
              "source_id": "h14",
              "actor": "user",
              "quote": "Your messaging app cannot send MMS messages.",
              "fact": "The MMS issue persists, indicating unresolved prerequisites."
            }
          ]
        }
      ],
      "coverage": {
        "status": "INSUFFICIENT",
        "reason": "The tool call `check_network_status` addresses only one diagnostic prerequisite (network status) for MMS but omits critical prerequisites such as network mode preference, APN/MMSC settings, Wi-Fi Calling status, and messaging app permissions. The policy requires verifying **all** prerequisites before concluding diagnostics or escalating."
